import { all, call, fork, put, takeEvery } from "redux-saga/effects";

// Login Redux States
import { FORGET_PASSWORD } from "./actionTypes";
import { userForgetPasswordError, userForgetPasswordSuccess } from "./actions";

// Include Backend Helper
import { forgetPassword } from "../../../helpers/backend_helper";

// If user is successfully sent a reset link, dispatch redux actions directly here.
function* forgetUser({ payload: { user, history } }) {
  try {
    const response = yield call(forgetPassword, "/forget-pwd", {
      email: user.email,
    });
    if (response) {
      yield put(
        userForgetPasswordSuccess(
          "Reset link has been sent to your mailbox. Please check there first."
        )
      );
    }
  } catch (error) {
    yield put(userForgetPasswordError(error));
  }
}

export function* watchUserPasswordForget() {
  yield takeEvery(FORGET_PASSWORD, forgetUser);
}

function* forgetPasswordSaga() {
  yield all([fork(watchUserPasswordForget)]);
}

export default forgetPasswordSaga;
