import classname from "classnames"
import PropTypes from "prop-types"
import React, { useEffect, useState } from "react"
import { FaRobot } from "react-icons/fa"
import { Link, withRouter } from "react-router-dom"
import { Collapse } from "reactstrap"

//i18n
import { withTranslation } from "react-i18next"

import { connect } from "react-redux"

const Navbar = props => {
  const [dashboard, setdashboard] = useState(false)

  const [app, setapp] = useState(false)

  const [jobsniping, setJobsniping] = useState(false)
  const [jobarbitrage, setJobarbitrage] = useState(false)
  const [jobcopy, setJobcopy] = useState(false)
  const [support, setSupport] = useState(false)

  const [invoice, setinvoice] = useState(false)
  const [auth, setauth] = useState(false)
  const [utility, setutility] = useState(false)

  useEffect(() => {
    var matchingMenuItem = null
    var ul = document.getElementById("navigation")
    var items = ul.getElementsByTagName("a")
    for (var i = 0; i < items.length; ++i) {
      if (props.location.pathname === items[i].pathname) {
        matchingMenuItem = items[i]
        break
      }
    }
    if (matchingMenuItem) {
      activateParentDropdown(matchingMenuItem)
    }
  })

  function activateParentDropdown(item) {
    item.classList.add("active")
    const parent = item.parentElement
    if (parent) {
      parent.classList.add("active") // li
      const parent2 = parent.parentElement
      parent2.classList.add("active") // li
      const parent3 = parent2.parentElement
      if (parent3) {
        parent3.classList.add("active") // li
        const parent4 = parent3.parentElement
        if (parent4) {
          parent4.classList.add("active") // li
          const parent5 = parent4.parentElement
          if (parent5) {
            parent5.classList.add("active") // li
            const parent6 = parent5.parentElement
            if (parent6) {
              parent6.classList.add("active") // li
            }
          }
        }
      }
    }
    return false
  }

  return (
    <React.Fragment>
      <div className="topnav">
        <div className="container-fluid">
          <nav
            className="navbar navbar-light navbar-expand-lg topnav-menu"
            id="navigation"
          >
            <Collapse
              isOpen={props.leftMenu}
              className="navbar-collapse"
              id="topnav-menu-content"
            >
              <ul className="navbar-nav">
                <li className="nav-item dropdown">
                  <Link
                    className="nav-link dropdown-toggle arrow-none"
                    onClick={e => {
                      e.preventDefault()
                      setdashboard(!dashboard)
                    }}
                    to="/dashboard"
                  >
                    <i className="bx bx-home-circle me-2"></i>
                    {props.t("Dashboard")} {props.menuOpen}
                    <div className="arrow-down"></div>
                  </Link>
                  <div
                    className={classname("dropdown-menu", { show: dashboard })}
                  >
                    <Link to="/crypto-exchange" className="dropdown-item">
                      {props.t("Crypto")}
                    </Link>
                    <Link to="#" className="dropdown-item">
                      {props.t("Portfolio")}
                    </Link>
                    <Link to="/settings" className="dropdown-item">
                      {props.t("Settings")}
                    </Link>
                  </div>
                </li>

                <li className="nav-item dropdown">
                  <Link
                    to="/#"
                    onClick={e => {
                      e.preventDefault()
                      setapp(!app)
                    }}
                    className="nav-link dropdown-togglez arrow-none"
                  >
                    <i className="bx bx-customize me-2"></i>
                    {props.t("Bot Activites")}{" "}
                    <div className="arrow-down"></div>
                  </Link>
                  <div className={classname("dropdown-menu", { show: app })}>
                    <div className="dropdown">
                      <Link
                        to="/#"
                        className="dropdown-item arrow-none"
                        onClick={e => {
                          e.preventDefault()
                          setJobsniping(!jobsniping)
                        }}
                      >
                        {props.t("Token Sniping")}{" "}
                        <div className="arrow-down"></div>
                      </Link>
                      <div
                        className={classname("dropdown-menu", {
                          show: jobsniping,
                        })}
                      >
                        <Link to="/token_sniper" className="dropdown-item">
                          {props.t("Active Snipes")}
                        </Link>

                        <Link to="/swap" className="dropdown-item">
                          {props.t("swap")}
                        </Link>
                        <Link to="/manage_tokens" className="dropdown-item">
                          {props.t("Add Tokens")}
                        </Link>
                        <Link to="/token_list" className="dropdown-item">
                          {props.t("List of tokens")}
                        </Link>
                        <Link to="/sniping_history" className="dropdown-item">
                          {props.t("Sniping History")}
                        </Link>
                        <Link to="/config" className="dropdown-item">
                          {props.t("Configuration")}
                        </Link>
                      </div>
                    </div>
                    <div className="dropdown">
                      <Link
                        to="/#"
                        className="dropdown-item arrow-none"
                        onClick={e => {
                          e.preventDefault()
                          setJobarbitrage(!jobarbitrage)
                        }}
                      >
                        {props.t("Arbitrage Trading")}{" "}
                        <div className="arrow-down"></div>
                      </Link>
                      <div
                        className={classname("dropdown-menu", {
                          show: jobarbitrage,
                        })}
                      >
                        <Link to="#" className="dropdown-item">
                          {props.t("Active Arbitrage")}
                        </Link>
                        <Link to="#" className="dropdown-item">
                          {props.t("Arbitrage History")}
                        </Link>
                        <Link to="#" className="dropdown-item">
                          {props.t("Configuration")}
                        </Link>
                      </div>
                    </div>
                    <div className="dropdown">
                      <Link
                        to="/#"
                        className="dropdown-item arrow-none"
                        onClick={e => {
                          e.preventDefault()
                          setJobcopy(!jobcopy)
                        }}
                      >
                        {props.t("Copy Trading")}{" "}
                        <div className="arrow-down"></div>
                      </Link>
                      <div
                        className={classname("dropdown-menu", {
                          show: jobcopy,
                        })}
                      >
                        <Link to="#" className="dropdown-item">
                          {props.t("Followed Wallets")}
                        </Link>
                        <Link to="#" className="dropdown-item">
                          {props.t("Copy History")}
                        </Link>
                        <Link to="#" className="dropdown-item">
                          {props.t("Configuration")}
                        </Link>
                      </div>
                    </div>
                  </div>
                </li>

                <li className="nav-item dropdown">
                  <Link
                    to="/#"
                    className="nav-link dropdown-toggle arrow-none"
                    onClick={e => {
                      e.preventDefault()
                      setSupport(!support)
                    }}
                  >
                    <i className="bx bx-collection me-2"></i>
                    {props.t("Help/Support")} <div className="arrow-down"></div>
                  </Link>
                  <div
                    className={classname("dropdown-menu", { show: support })}
                  >
                    <div className="dropdown">
                      <Link to="/#" className="dropdown-item arrow-none">
                        {props.t("FAQs")}
                      </Link>
                      <Link to="/#" className="dropdown-item arrow-none">
                        {props.t("Tutorials")}
                      </Link>
                      <Link to="/#" className="dropdown-item arrow-none">
                        {props.t("Contact")}
                      </Link>
                    </div>
                  </div>
                </li>
                <li>
                  <Link to="/chatbot" className="nav-link">
                    <FaRobot className="me-2" /> {/* Bot icon */}
                    {props.t("Chatbot")}
                  </Link>
                </li>
              </ul>
            </Collapse>
          </nav>
        </div>
      </div>
    </React.Fragment>
  )
}

Navbar.propTypes = {
  leftMenu: PropTypes.any,
  location: PropTypes.any,
  menuOpen: PropTypes.any,
  t: PropTypes.any,
}

const mapStatetoProps = state => {
  const { leftMenu } = state.Layout
  return { leftMenu }
}

export default withRouter(
  connect(mapStatetoProps, {})(withTranslation()(Navbar))
)
