import { useEffect, useState } from 'react';
import { Button, Form, Modal, Table } from 'react-bootstrap';
import { FaCog, FaEdit, FaPlus, FaShoppingCart, FaTrash } from 'react-icons/fa';
import * as apiServices from '../../helpers/apiServices';
import SnipingConfig from './SnipingConfig';

function TokenList() {
  const [tokens, setTokens] = useState([]);
  const [configProfiles, setConfigProfiles] = useState([]);
  const [showAddTokenModal, setShowAddTokenModal] = useState(false);
  const [showConfigModal, setShowConfigModal] = useState(false);
  const [newToken, setNewToken] = useState({ name: '', address: '', configProfileId: '' });
  const [editToken, setEditToken] = useState(null);

  useEffect(() => {
    fetchConfigurationProfiles();
    fetchSnipingTokens(); // Initial fetch for tokens
    initializeWebSocket(); // Start WebSocket for real-time updates
  }, []);

  const fetchSnipingTokens = async () => {
    try {
      const response = await apiServices.getSnipingTokens();
      console.log("Fetched tokens:", response);
      setTokens(response);
    } catch (error) {
      console.error("Error fetching sniping tokens:", error);
    }
  };

  const fetchConfigurationProfiles = async () => {
    try {
      const response = await apiServices.getConfigurationProfiles();
      console.log("Fetched configuration profiles:", response);
      setConfigProfiles(response);
    } catch (error) {
      console.error("Error fetching configuration profiles:", error);
    }
  };

  const initializeWebSocket = () => {
    const socket = apiServices.createWebSocket();

    socket.onmessage = (event) => {
      const data = JSON.parse(event.data);
      console.log("Received WebSocket message:", data);

      if (data.tokens) {
        setTokens((prevTokens) => {
          // Merge new tokens with existing ones
          const updatedTokens = [...prevTokens];
          data.tokens.forEach((newToken) => {
            const existingTokenIndex = updatedTokens.findIndex((token) => token.id === newToken.id);
            if (existingTokenIndex !== -1) {
              // Update existing token
              updatedTokens[existingTokenIndex] = newToken;
            } else {
              // Add new token
              updatedTokens.push(newToken);
            }
          });
          return updatedTokens;
        });
      }
    };

    socket.onclose = () => {
      console.log("WebSocket connection closed.");
    };

    socket.onerror = (error) => {
      console.error("WebSocket error:", error);
    };

    return () => {
      socket.close();
    };
  };

  const handleAddToken = async () => {
    try {
      const payload = {
        name: newToken.name,
        address: newToken.address,
        config_profile_id: newToken.configProfileId,
      };

      if (editToken) {
        await apiServices.updateSnipingToken(editToken.id, payload);
        fetchSnipingTokens(); // Fetch updated tokens
        setEditToken(null);
      } else {
        await apiServices.addSnipingToken(payload);
        fetchSnipingTokens(); // Fetch updated tokens
      }

      setNewToken({ name: '', address: '', configProfileId: '' });
      setShowAddTokenModal(false);
    } catch (error) {
      console.error("Error adding/updating token:", error);
    }
  };

  const handleEditToken = (token) => {
    setNewToken({
      name: token.name,
      address: token.address,
      configProfileId: configProfiles.find((p) => p.profile_name === token.configuration_profile)?.id || '',
    });
    setEditToken(token);
    setShowAddTokenModal(true);
  };

  const handleDeleteToken = async (tokenId) => {
    try {
      await apiServices.deleteSnipingToken(tokenId);
      fetchSnipingTokens(); // Fetch updated tokens
    } catch (error) {
      console.error("Error deleting token:", error);
    }
  };

  const handleBuyToken = (tokenId) => {
    console.log(`Manual buy triggered for token ID: ${tokenId}`);
    // Implement the actual API call if needed
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-2">
        <h5 className="text-white mb-0">Token List</h5>
        <div>
          <FaPlus
            size={24}
            color="green"
            onClick={() => setShowAddTokenModal(true)}
            style={{ cursor: 'pointer', marginRight: '10px' }}
          />
          <FaCog
            size={24}
            color="white"
            onClick={() => setShowConfigModal(true)}
            style={{ cursor: 'pointer' }}
          />
        </div>
      </div>
      <div className="table-container" style={{ maxHeight: '300px', overflowY: 'auto' }}>
        <Table striped bordered hover variant="dark" className="rounded">
          <thead>
            <tr>
              <th>Name</th>
              <th>Address</th>
              <th>Config Profile</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {tokens.map((token) => {
              const profile = configProfiles.find((p) => p.profile_name === token.configuration_profile);
              return (
                <tr key={token.id}>
                  <td>{token.name}</td>
                  <td>{token.address}</td>
                  <td>{profile?.profile_name || 'None'}</td>
                  <td>
                    {profile && !profile.auto_buy && (
                      <FaShoppingCart
                        size={20}
                        color="orange"
                        style={{ cursor: 'pointer', marginRight: '10px' }}
                        onClick={() => handleBuyToken(token.id)}
                      />
                    )}
                    <FaEdit
                      size={20}
                      color="black"
                      style={{ cursor: 'pointer', marginRight: '10px' }}
                      onClick={() => handleEditToken(token)}
                    />
                    <FaTrash
                      size={20}
                      color="red"
                      style={{ cursor: 'pointer' }}
                      onClick={() => handleDeleteToken(token.id)}
                    />
                  </td>
                </tr>
              );
            })}
          </tbody>
        </Table>
      </div>

      {/* Add/Edit Token Modal */}
      <Modal show={showAddTokenModal} onHide={() => { setShowAddTokenModal(false); setEditToken(null); }}>
        <Modal.Header closeButton>
          <Modal.Title>{editToken ? 'Edit Token' : 'Add New Token'}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Token Name</Form.Label>
              <Form.Control
                type="text"
                value={newToken.name}
                onChange={(e) => setNewToken({ ...newToken, name: e.target.value })}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Token Address</Form.Label>
              <Form.Control
                type="text"
                value={newToken.address}
                onChange={(e) => setNewToken({ ...newToken, address: e.target.value })}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Choose Configuration Profile</Form.Label>
              <Form.Select
                value={newToken.configProfileId}
                onChange={(e) => setNewToken({ ...newToken, configProfileId: parseInt(e.target.value, 10) || '' })}
              >
                <option value="">Select a profile</option>
                {configProfiles.map((profile) => (
                  <option key={profile.id} value={profile.id}>
                    {profile.profile_name}
                  </option>
                ))}
              </Form.Select>
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button
            variant="secondary"
            onClick={() => {
              setShowAddTokenModal(false);
              setEditToken(null);
            }}
          >
            Close
          </Button>
          <Button variant="primary" onClick={handleAddToken}>
            {editToken ? 'Save Changes' : 'Add Token'}
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Sniping Config Modal */}
      <SnipingConfig showConfigModal={showConfigModal} onHide={() => setShowConfigModal(false)} />
    </div>
  );
}

export default TokenList;
