import { all, call, fork, put, takeEvery } from "redux-saga/effects";
import { loginUser as loginAPI } from "../../../helpers/apiServices";
import { LOGIN_USER, LOGOUT_USER } from "./actionTypes";
import { apiError, loginSuccess, logoutUserSuccess } from "./actions";

function* loginUserSaga({ payload: { user, history } }) {
  try {
    const response = yield call(loginAPI, user);
    if (response) {
      localStorage.setItem("authUser", JSON.stringify(response));
      yield put(loginSuccess(response));
      history.push("/dashboard");
    } else {
      yield put(apiError("Invalid login response"));
    }
  } catch (error) {
    yield put(apiError(error?.error || "Login failed"));
  }
}

function* logoutUserSaga({ payload: { history } }) {
  try {
    localStorage.removeItem("authUser");
    yield put(logoutUserSuccess());
    history.push("/login");
  } catch (error) {
    yield put(apiError(error.message || "Logout failed"));
  }
}

export function* watchUserLogin() {
  yield takeEvery(LOGIN_USER, loginUserSaga);
}

export function* watchUserLogout() {
  yield takeEvery(LOGOUT_USER, logoutUserSaga);
}

export default function* authSaga() {
  yield all([fork(watchUserLogin), fork(watchUserLogout)]);
}
