// src/components/ListOfTokens.js

import { useEffect, useState } from 'react';
import { fetchAllTokens } from '../../helpers/apiServices';
import './bot.css';

function ListOfTokens() {
  const [tokens, setTokens] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const getTokens = async () => {
      try {
        setLoading(true);
        const tokenData = await fetchAllTokens();
        setTokens(tokenData);
      } catch (error) {
        console.error("Failed to fetch tokens:", error);
      } finally {
        setLoading(false);
      }
    };

    getTokens();

    const ws = new WebSocket('wss://api.dexscreener.com/ws');

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);
      if (data.type === 'update') {
        setTokens((prevTokens) =>
          prevTokens.map((token) =>
            token.pairAddress === data.pairAddress ? { ...token, ...data } : token
          )
        );
      }
    };

    return () => {
      ws.close();
    };
  }, []);

  if (loading) {
    return <div className="loading-message">Loading tokens...</div>;
  }

  return (
    <div className="token-list-container">
      <h2 className="token-list-title">All Tokens</h2>
      <div className="token-list-table-container">
        <table className="token-list-table">
          <thead>
            <tr>
              <th>Token</th>
              <th>Address</th>
              <th>Price (USD)</th>
              <th>Age</th>
              <th>Buys (24h)</th>
              <th>Sells (24h)</th>
              <th>Volume (24h USD)</th>
              <th>Price Change (5m)</th>
              <th>Price Change (1h)</th>
              <th>Price Change (6h)</th>
              <th>Price Change (24h)</th>
              <th>Market Cap (FDV)</th>
            </tr>
          </thead>
          <tbody>
            {tokens.map((token, index) => (
              <tr key={index}>
                <td>{token.baseToken?.name} / {token.baseToken?.symbol}</td>
                <td>{token.baseToken?.address}</td>
                <td>${token.priceUsd ? parseFloat(token.priceUsd).toFixed(2) : 'N/A'}</td>
                <td>{token.pairCreatedAt ? new Date(token.pairCreatedAt * 1000).toLocaleDateString() : 'N/A'}</td>
                <td>{token.txns?.h24?.buys ?? 'N/A'}</td>
                <td>{token.txns?.h24?.sells ?? 'N/A'}</td>
                <td>${token.volume?.h24 ? parseFloat(token.volume.h24).toLocaleString() : 'N/A'}</td>
                <td>{token.priceChange?.m5 ?? 'N/A'}%</td>
                <td>{token.priceChange?.h1 ?? 'N/A'}%</td>
                <td>{token.priceChange?.h6 ?? 'N/A'}%</td>
                <td>{token.priceChange?.h24 ?? 'N/A'}%</td>
                <td>${token.fdv ? parseFloat(token.fdv).toLocaleString() : 'N/A'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default ListOfTokens;
