import {
  API_ERROR,
  LOGIN_SUCCESS,
  LOGIN_USER,
  LOGOUT_USER,
  LOGOUT_USER_SUCCESS,
} from "./actionTypes";

const initialState = {
  error: "",
  loading: false,
};

const login = (state = initialState, action) => {
  switch (action.type) {
    case LOGIN_USER:
      return {
        ...state,
        loading: true,
        error: "",  // Clear previous errors on new login attempt
      };
    case LOGIN_SUCCESS:
      return {
        ...state,
        loading: false,
        error: "",  // Clear errors upon successful login
      };
    case LOGOUT_USER:
      return {
        ...state,
      };
    case LOGOUT_USER_SUCCESS:
      return {
        ...state,
      };
    case API_ERROR:
      return {
        ...state,
        error: action.payload, // Update error message
        loading: false,
      };
    default:
      return state;
  }
};

export default login;
