import { all, call, fork, put, takeEvery } from "redux-saga/effects";

// Profile Redux States
import { EDIT_PROFILE } from "./actionTypes";
import { profileError, profileSuccess } from "./actions";

// Include Backend Helper
import { editUserProfile } from "../../../helpers/backend_helper";

function* editProfile({ payload: { user } }) {
  try {
    // Using real backend
    const response = yield call(editUserProfile, {
      username: user.username,
      idx: user.idx,
    });
    yield put(profileSuccess(response));
  } catch (error) {
    yield put(profileError(error));
  }
}

// Watch for profile edit actions
export function* watchProfile() {
  yield takeEvery(EDIT_PROFILE, editProfile);
}

// Root Saga for profile
function* ProfileSaga() {
  yield all([fork(watchProfile)]);
}

export default ProfileSaga;
