import {
  ArrowDownOutlined,
  DownOutlined,
  SettingOutlined,
} from "@ant-design/icons";
import { Modal, Popover, Radio, message } from "antd";
import { useEffect, useState } from "react";
import {
  executeTransaction,
  fetchPrices,
  fetchTokensFromBackend,
  getSelectedWallet,
} from "../../helpers/apiServices";
import "./swap.css";

function Swap({ address, isConnected }) {
  const [messageApi, contextHolder] = message.useMessage();
  const [slippage, setSlippage] = useState(0.5);
  const [tokenOneAmount, setTokenOneAmount] = useState("");
  const [tokenTwoAmount, setTokenTwoAmount] = useState("");
  const [tokenOne, setTokenOne] = useState({});
  const [tokenTwo, setTokenTwo] = useState({});
  const [isOpen, setIsOpen] = useState(false);
  const [changeToken, setChangeToken] = useState(1);
  const [prices, setPrices] = useState(null);
  const [selectedWallet, setSelectedWallet] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [tokenList, setTokenList] = useState([]);

  // Debug logs
  useEffect(() => {
    console.log("isConnected:", isConnected);
    console.log("tokenOneAmount:", tokenOneAmount);
    console.log("selectedWallet:", selectedWallet);
    console.log("tokenOne:", tokenOne);
    console.log("tokenTwo:", tokenTwo);
  }, [isConnected, tokenOneAmount, selectedWallet, tokenOne, tokenTwo]);

  // Fetch tokens from the backend on component mount
  useEffect(() => {
    async function fetchTokens() {
      try {
        const tokens = await fetchTokensFromBackend();
        if (tokens && tokens.length > 0) {
          setTokenList(tokens);
          setTokenOne(tokens[0]);
          setTokenTwo(tokens[1]);
        }
      } catch (error) {
        console.error("Error fetching tokens:", error);
        messageApi.error("Failed to fetch tokens.");
      }
    }
    fetchTokens();
  }, []);

  useEffect(() => {
    async function fetchSelectedWallet() {
      try {
        const wallet = await getSelectedWallet();
        setSelectedWallet(wallet);
      } catch (error) {
        message.error("Failed to fetch selected wallet");
      }
    }
    fetchSelectedWallet();
  }, []);

  useEffect(() => {
    if (tokenOne.address && tokenTwo.address) {
      fetchPricesWrapper(tokenOne.address, tokenTwo.address);
    }
  }, [tokenOne, tokenTwo]);

  function handleSlippageChange(e) {
    setSlippage(Number(e.target.value));
  }

  function changeAmount(e) {
    const value = e.target.value;
    if (!isNaN(value) && value.trim() !== "") {
      setTokenOneAmount(value);
      if (value && prices && !isNaN(parseFloat(prices.ratio))) {
        const calculatedAmount = (value * parseFloat(prices.ratio)).toFixed(10);
        setTokenTwoAmount(calculatedAmount);
      } else {
        setTokenTwoAmount("");
      }
    } else {
      setTokenOneAmount("");
    }
  }

  function switchTokens() {
    setPrices(null);
    setTokenOneAmount("");
    setTokenTwoAmount("");
    setTokenOne(tokenTwo);
    setTokenTwo(tokenOne);
    fetchPricesWrapper(tokenTwo.address, tokenOne.address);
  }

  function openModal(asset) {
    setChangeToken(asset);
    setIsOpen(true);
  }

  function modifyToken(i) {
    setPrices(null);
    setTokenOneAmount("");
    setTokenTwoAmount("");
    if (changeToken === 1) {
      setTokenOne(tokenList[i]);
      fetchPricesWrapper(tokenList[i].address, tokenTwo.address);
    } else {
      setTokenTwo(tokenList[i]);
      fetchPricesWrapper(tokenOne.address, tokenList[i].address);
    }
    setIsOpen(false);
  }

  async function fetchPricesWrapper(one, two) {
    try {
      const priceData = await fetchPrices(one, two);
      if (priceData && priceData[one] && priceData[two]) {
        const priceOne = parseFloat(priceData[one].price);
        const priceTwo = parseFloat(priceData[two].price);
        if (priceOne && priceTwo) {
          const ratio = priceOne / priceTwo;
          setPrices({ ratio });
        } else {
          messageApi.error("Invalid price data received.");
        }
      } else {
        messageApi.error("Price data not found for one or both tokens.");
      }
    } catch (error) {
      console.error("Error fetching prices:", error);
      messageApi.error("Failed to fetch prices.");
    }
  }

  async function fetchDexSwapWrapper() {
    if (!selectedWallet) {
      messageApi.error("Selected wallet not found.");
      return;
    }

    if (!tokenOneAmount || isNaN(parseFloat(tokenOneAmount)) || parseFloat(tokenOneAmount) <= 0) {
      messageApi.error("Invalid token amount.");
      return;
    }

    const amountInSmallestUnit = Math.round(tokenOneAmount * 1e6);
    const transactionData = {
      wallet_id: selectedWallet.id,
      token_from: tokenOne.address,
      token_to: tokenTwo.address,
      amount_from: amountInSmallestUnit,
      slippage: slippage,
    };

    setIsLoading(true);
    try {
      const response = await executeTransaction(transactionData);
      if (response.explorer_link) {
        window.open(response.explorer_link, "_blank"); // Open in a new window for success or failure
      }
      if (response.status === "SUCCESS") {
        messageApi.success("Swap executed successfully!");
        setTokenTwoAmount(response.amount_to);
      } else {
        messageApi.error("Swap execution failed.");
      }
    } catch (error) {
      console.error("Swap execution failed:", error);
      messageApi.error("Swap execution failed. Check console for details.");
    } finally {
      setIsLoading(false);
    }
  }

  const settings = (
    <div>
      <div>Slippage Tolerance</div>
      <Radio.Group value={slippage} onChange={handleSlippageChange}>
        <Radio.Button value={0.5}>0.5%</Radio.Button>
        <Radio.Button value={2.5}>2.5%</Radio.Button>
        <Radio.Button value={5}>5.0%</Radio.Button>
      </Radio.Group>
    </div>
  );

  return (
    <div className="container">
      {contextHolder}
      <Modal
        open={isOpen}
        footer={null}
        onCancel={() => setIsOpen(false)}
        title="Select a token"
      >
        <div className="modalContent">
          {tokenList?.map((e, i) => (
            <div
              className="tokenChoice"
              key={i}
              onClick={() => modifyToken(i)}
            >
              <img src={e.img} alt={e.ticker} className="tokenLogo" />
              <div className="tokenChoiceNames">
                <div className="tokenName">{e.name}</div>
                <div className="tokenTicker">{e.ticker}</div>
              </div>
            </div>
          ))}
        </div>
      </Modal>
      <div className="tradeBox">
        <div className="tradeBoxHeader">
          <h4>Swap</h4>
          <Popover
            content={settings}
            title="Settings"
            trigger="click"
            placement="bottomRight"
          >
            <SettingOutlined className="cog" />
          </Popover>
        </div>
        <div className="inputs">
          <div className="inputContainer">
            <input
              type="text"
              placeholder="0.00"
              value={tokenOneAmount}
              onChange={changeAmount}
            />
            <div className="tokenSelect" onClick={() => openModal(1)}>
              <img src={tokenOne.img} alt={tokenOne.ticker} />
              <span>{tokenOne.ticker}</span>
              <DownOutlined />
            </div>
          </div>
          <div className="switchButton" onClick={switchTokens}>
            <ArrowDownOutlined />
          </div>
          <div className="inputContainer">
            <input
              type="text"
              placeholder="0.00"
              value={tokenTwoAmount}
              readOnly
            />
            <div className="tokenSelect" onClick={() => openModal(2)}>
              <img src={tokenTwo.img} alt={tokenTwo.ticker} />
              <span>{tokenTwo.ticker}</span>
              <DownOutlined />
            </div>
          </div>
        </div>
        <button
          className="swapButton"
          onClick={fetchDexSwapWrapper}
          disabled={
            !tokenOneAmount ||
            isNaN(parseFloat(tokenOneAmount)) ||
            parseFloat(tokenOneAmount) <= 0 ||
            isConnected ||
            isLoading ||
            !selectedWallet ||
            !tokenOne.address ||
            !tokenTwo.address
          }
        >
          {isLoading ? "Swapping..." : "Swap"}
        </button>
      </div>
    </div>
  );
}

export default Swap;
