import { useEffect, useState } from 'react';
import * as apiServices from '../../helpers/apiServices';

function SnipingHistory() {
  const [snipingHistory, setSnipingHistory] = useState([]);

  useEffect(() => {
    fetchSnipingHistory();
  }, []);

  const fetchSnipingHistory = async () => {
    try {
      const response = await apiServices.getSnipingHistory();
      if (Array.isArray(response)) {
        setSnipingHistory(response);
      } else {
        console.error("Unexpected response format:", response);
      }
    } catch (error) {
      console.error("Error fetching sniping history:", error);
    }
  };

  return (
    <div className="p-3 terminal rounded shadow-sm">
      <h5 className="text-white">Transaction History</h5>
      <div className="transaction-history p-3 bg-secondary rounded" style={{ height: '300px', overflowY: 'auto' }}>
        {snipingHistory.length > 0 ? (
          snipingHistory.map((history, index) => (
            <div key={history.id || index} className="text-light mb-2">
              <p><strong>Timestamp:</strong> {history.timestamp ? new Date(history.timestamp).toLocaleString() : 'N/A'}</p>
              <p><strong>Token:</strong> {history.token || 'N/A'}</p>
              <p><strong>Transaction Type:</strong> {history.transactionType || 'N/A'}</p>
              <p><strong>Status:</strong> {history.status || 'N/A'}</p>
              <p><strong>Details:</strong> {history.details || 'N/A'}</p>
              <hr className="bg-light" />
            </div>
          ))
        ) : (
          <div className="text-muted">No transaction history available.</div>
        )}
      </div>
    </div>
  );
}

export default SnipingHistory;
