import { useEffect, useState } from 'react';
import { fetchTokens } from '../../helpers/apiServices';
import './bot.css';

function ManageTokens() {
  const [tokens, setTokens] = useState([]);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchTokensList();
  }, []);

  // Fetch the list of tokens in the user's wallet
  const fetchTokensList = async () => {
    try {
      const data = await fetchTokens();
      // Ensure data is an array of tokens with the required properties
      const formattedData = data.map((token) => ({
        name: token.name || 'N/A',
        address: token.address || 'N/A',
        balance: token.balance || 0,
        symbol: token.symbol || 'N/A',
      }));
      setTokens(formattedData);
    } catch (error) {
      console.error("Error fetching tokens:", error);
      setError('Failed to fetch tokens. Please try again.');
    }
  };

  return (
    <div className="padding-top-container manage-tokens-container">
      <h2 className="manage-tokens-header">Tokens in Your Wallet</h2>
      {error && <p className="error-message">{error}</p>}

      {/* Token List Section */}
      <table className="token-list-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Address</th>
            <th>Balance</th>
            <th>Symbol</th>
          </tr>
        </thead>
        <tbody>
          {tokens.length > 0 ? (
            tokens.map((token, index) => (
              <tr key={index}>
                <td>{token.name}</td>
                <td>{token.address}</td>
                <td>{token.balance}</td>
                <td>{token.symbol}</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="4" className="text-center">No tokens found in your wallet.</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

export default ManageTokens;
