import { useEffect, useState } from 'react';
import { Button, Form, Modal, Table } from 'react-bootstrap';
import { FaEdit, FaPlus, FaTrash } from 'react-icons/fa';
import * as apiServices from '../../helpers/apiServices';

function SnipingConfig({ showConfigModal, onHide }) {
  const [configProfiles, setConfigProfiles] = useState([]);
  const [showAddConfigModal, setShowAddConfigModal] = useState(false);
  const [newConfigProfile, setNewConfigProfile] = useState({
    profile_name: '',
    buy_amount: '',
    take_profit: '',
    stop_loss: '',
    slippage: '',
    autoBuy: false,
  });
  const [editConfigProfile, setEditConfigProfile] = useState(null);

  useEffect(() => {
    if (showConfigModal) {
      fetchConfigurationProfiles();
    }
  }, [showConfigModal]);

  const fetchConfigurationProfiles = async () => {
    try {
      const response = await apiServices.getConfigurationProfiles();
      const normalizedProfiles = response.map(profile => ({
        ...profile,
        autoBuy: profile.auto_buy, // Normalize `auto_buy` to `autoBuy` for consistent state handling
      }));
      setConfigProfiles(normalizedProfiles);
    } catch (error) {
      console.error('Error fetching configuration profiles:', error);
    }
  };

  const handleAddConfigProfile = async () => {
    // Basic validation to prevent empty or invalid field submission
    if (
      !newConfigProfile.profile_name ||
      newConfigProfile.buy_amount <= 0 ||
      newConfigProfile.take_profit <= 0 ||
      newConfigProfile.stop_loss <= 0 ||
      newConfigProfile.slippage <= 0
    ) {
      alert('All fields must be filled with valid values.');
      return;
    }

    try {
      const payload = {
        ...newConfigProfile,
        auto_buy: newConfigProfile.autoBuy, // Convert `autoBuy` to `auto_buy` for backend compatibility
      };

      if (editConfigProfile) {
        await apiServices.updateConfigurationProfile(editConfigProfile.id, payload);
        setConfigProfiles(prevProfiles =>
          prevProfiles.map(profile =>
            profile.id === editConfigProfile.id ? { ...editConfigProfile, ...newConfigProfile } : profile
          )
        );
        setEditConfigProfile(null);
      } else {
        await apiServices.addConfigurationProfile(payload);
        fetchConfigurationProfiles();
      }

      // Reset form and close modal
      setNewConfigProfile({
        profile_name: '',
        buy_amount: '',
        take_profit: '',
        stop_loss: '',
        slippage: '',
        autoBuy: false,
      });
      setShowAddConfigModal(false);
    } catch (error) {
      console.error('Error adding/updating configuration profile:', error);
    }
  };

  const handleEditConfig = (profile) => {
    setNewConfigProfile({
      ...profile,
      autoBuy: profile.autoBuy, // Ensure `autoBuy` is included in the state for the modal
    });
    setEditConfigProfile(profile);
    setShowAddConfigModal(true);
  };

  const handleDeleteConfig = async (profileId) => {
    try {
      await apiServices.deleteConfigurationProfile(profileId);
      fetchConfigurationProfiles();
    } catch (error) {
      console.error('Error deleting configuration profile:', error);
    }
  };

  const handleChange = (field, value) => {
    setNewConfigProfile(prevState => ({
      ...prevState,
      [field]: field === 'autoBuy' ? value === 'true' : value, // Convert 'autoBuy' to a boolean
    }));
  };

  return (
    <Modal show={showConfigModal} onHide={onHide} size="lg">
      <Modal.Header closeButton>
        <Modal.Title>Manage Configuration Profiles</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <Button variant="primary" className="mb-3" onClick={() => setShowAddConfigModal(true)}>
          <FaPlus /> Add New Profile
        </Button>
        <div className="table-container" style={{ maxHeight: '300px', overflowY: 'auto' }}>
          <Table striped bordered hover variant="dark" className="rounded">
            <thead>
              <tr>
                <th>#</th>
                <th>Profile Name</th>
                <th>Buy Amount</th>
                <th>Take Profit</th>
                <th>Stop Loss</th>
                <th>Slippage</th>
                <th>Auto-Buy</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {configProfiles.map((profile) => (
                <tr key={profile.id}>
                  <td>{profile.id}</td>
                  <td>{profile.profile_name}</td>
                  <td>{profile.buy_amount}</td>
                  <td>{profile.take_profit}</td>
                  <td>{profile.stop_loss}</td>
                  <td>{profile.slippage}</td>
                  <td>{profile.autoBuy ? 'True' : 'False'}</td>
                  <td>
                    <FaEdit
                      className="me-3 text-info"
                      style={{ cursor: 'pointer' }}
                      onClick={() => handleEditConfig(profile)}
                    />
                    <FaTrash
                      className="text-danger"
                      style={{ cursor: 'pointer' }}
                      onClick={() => handleDeleteConfig(profile.id)}
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        </div>
      </Modal.Body>

      {/* Add/Edit Configuration Profile Modal */}
      <Modal show={showAddConfigModal} onHide={() => setShowAddConfigModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>{editConfigProfile ? 'Edit Configuration Profile' : 'Add New Configuration Profile'}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Profile Name</Form.Label>
              <Form.Control
                type="text"
                value={newConfigProfile.profile_name}
                onChange={(e) => handleChange('profile_name', e.target.value)}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Buy Amount</Form.Label>
              <Form.Control
                type="number"
                value={newConfigProfile.buy_amount}
                onChange={(e) => handleChange('buy_amount', parseFloat(e.target.value) || '')}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Take Profit</Form.Label>
              <Form.Control
                type="number"
                value={newConfigProfile.take_profit}
                onChange={(e) => handleChange('take_profit', parseFloat(e.target.value) || '')}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Stop Loss</Form.Label>
              <Form.Control
                type="number"
                value={newConfigProfile.stop_loss}
                onChange={(e) => handleChange('stop_loss', parseFloat(e.target.value) || '')}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Slippage</Form.Label>
              <Form.Control
                type="number"
                value={newConfigProfile.slippage}
                onChange={(e) => handleChange('slippage', parseFloat(e.target.value) || '')}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Auto-Buy</Form.Label>
              <Form.Select
                value={newConfigProfile.autoBuy}
                onChange={(e) => handleChange('autoBuy', e.target.value === 'true')}
              >
                <option value="true">True</option>
                <option value="false">False</option>
              </Form.Select>
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowAddConfigModal(false)}>Close</Button>
          <Button variant="primary" onClick={handleAddConfigProfile}>{editConfigProfile ? 'Save Changes' : 'Add Profile'}</Button>
        </Modal.Footer>
      </Modal>
    </Modal>
  );
}

export default SnipingConfig;
