import { all, call, fork, put, takeEvery } from "redux-saga/effects";
import { registerUser as registerUserApi } from "../../../helpers/apiServices";
import { REGISTER_USER } from "./actionTypes";
import { registerUserFailed, registerUserSuccessful } from "./actions";

function* registerUserSaga({ payload: { user } }) {
  try {
    const response = yield call(registerUserApi, user);
    yield put(registerUserSuccessful(response));
  } catch (error) {
    const errorMessage = error.error || "Registration failed";
    yield put(registerUserFailed(errorMessage));
  }
}

export function* watchUserRegister() {
  yield takeEvery(REGISTER_USER, registerUserSaga);
}

function* accountSaga() {
  yield all([fork(watchUserRegister)]);
}

export default accountSaga;
