import { Button, Card, Input, Modal } from 'antd';
import { useEffect, useState } from 'react';
import {
  addWallet,
  deleteWallet,
  getWallets,
  updateWallet,
} from '../../helpers/apiServices';
import './manageWallets.css';

function ManageWallets() {
  const [wallets, setWallets] = useState([]);
  const [newWallet, setNewWallet] = useState({ name: '', public_key: '', private_key: '' });
  const [editingWallet, setEditingWallet] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentPage, setCurrentPage] = useState(0);

  useEffect(() => {
    fetchWalletData();
  }, []);

  useEffect(() => {
    if (currentPage >= wallets.length) {
      setCurrentPage(wallets.length - 1);
    }
  }, [wallets]);

  const fetchWalletData = async () => {
    try {
      const walletData = await getWallets();
      console.log('Fetched wallet data:', walletData);
      
      if (Array.isArray(walletData)) {
        setWallets(walletData.map(wallet => ({
          ...wallet,
          tokens: Array.isArray(wallet.tokens) ? wallet.tokens : [], // Ensure tokens is an array
        })));
      } else {
        console.error('Expected an array but received:', walletData);
        setWallets([]); // Prevent setting invalid state
      }
    } catch (error) {
      console.error('Error fetching wallet data:', error);
      setWallets([]); // Prevent undefined state in case of an error
    }
  };

  const handleAddWallet = async () => {
    try {
      await addWallet(newWallet);
      setNewWallet({ name: '', public_key: '', private_key: '' });
      fetchWalletData();
      setIsModalOpen(false);
    } catch (error) {
      console.error('Error adding wallet:', error);
    }
  };

  const handleEditWallet = async (id) => {
    try {
      await updateWallet(id, { name: editingWallet.name });
      setEditingWallet(null);
      fetchWalletData();
    } catch (error) {
      console.error('Error updating wallet:', error);
    }
  };

  const handleDeleteWallet = async (id) => {
    try {
      await deleteWallet(id);
      setCurrentPage(0);
      fetchWalletData();
    } catch (error) {
      console.error('Error deleting wallet:', error);
    }
  };

  const handleNextPage = () => {
    if (currentPage < wallets.length - 1) {
      setCurrentPage(currentPage + 1);
    }
  };

  const handlePreviousPage = () => {
    if (currentPage > 0) {
      setCurrentPage(currentPage - 1);
    }
  };

  return (
    <div className="wallets-container">
      <h2 className="wallets-title">Manage Wallets</h2>
      <Button type="primary" onClick={() => setIsModalOpen(true)} className="add-wallet-button">
        + Add Wallet
      </Button>

      {wallets.length > 0 && wallets[currentPage] ? (
        <Card className="wallet-card">
          <div className="wallet-detail">
            <strong>ID:</strong> {wallets[currentPage].id}
          </div>
          <div className="wallet-detail">
            <strong>Name:</strong>{' '}
            {editingWallet && editingWallet.id === wallets[currentPage].id ? (
              <Input
                value={editingWallet.name}
                onChange={(e) => setEditingWallet({ ...editingWallet, name: e.target.value })}
                className="wallets-input-field"
              />
            ) : (
              wallets[currentPage].name
            )}
          </div>
          <div className="wallet-detail">
            <strong>SOL Balance:</strong> {wallets[currentPage].balance} SOL
            <div className="wallet-converted">
              (~${(wallets[currentPage].balance * wallets[currentPage].solPrice).toFixed(2)} USD)
            </div>
          </div>
          <div className="wallet-detail">
            <strong>Public Key:</strong>{' '}
            <a
              href={`https://explorer.solana.com/address/${wallets[currentPage].public_key}?cluster=mainnet-beta`}
              target="_blank"
              rel="noopener noreferrer"
              className="wallet-link"
            >
              {wallets[currentPage].public_key}
            </a>
          </div>
          <div className="wallet-detail">
            <strong>Tokens:</strong>
            {Array.isArray(wallets[currentPage].tokens) && wallets[currentPage].tokens.length > 0 ? (
              wallets[currentPage].tokens.map((token, index) => (
                <div key={index} className="token-details">
                  <img src={token.img} alt={token.name} className="token-logo" />
                  <span>{token.name} ({token.balance} tokens)</span>
                  <div className="token-metadata">Mint: {token.mint_address}</div>
                  <div className="token-metadata">Account: {token.account_pubkey}</div>
                  <div className="token-metadata">
                    USD Value: ~${(token.balance * token.price).toFixed(2)} USD
                  </div>
                </div>
              ))
            ) : (
              <p>No tokens available</p>
            )}
          </div>
          <div className="wallet-more-details">
            <a
              href={`https://explorer.solana.com/address/${wallets[currentPage].public_key}?cluster=mainnet-beta`}
              target="_blank"
              rel="noopener noreferrer"
              className="wallet-link"
            >
              More Details
            </a>
          </div>
          <div className="wallet-actions">
            {editingWallet && editingWallet.id === wallets[currentPage].id ? (
              <Button type="link" onClick={() => handleEditWallet(wallets[currentPage].id)} className="action-button">
                Save
              </Button>
            ) : (
              <>
                <Button type="link" onClick={() => setEditingWallet(wallets[currentPage])} className="action-button">
                  Edit
                </Button>
                <Button type="link" danger onClick={() => handleDeleteWallet(wallets[currentPage].id)} className="action-button">
                  Delete
                </Button>
              </>
            )}
          </div>
        </Card>
      ) : (
        <p>No wallets to display</p>
      )}

      <div className="pagination-controls">
        <Button onClick={handlePreviousPage} disabled={currentPage === 0} className="pagination-button">
          Previous
        </Button>
        <Button onClick={handleNextPage} disabled={currentPage >= wallets.length - 1} className="pagination-button">
          Next
        </Button>
      </div>

      {/* Add Wallet Modal */}
      <Modal
        title="Add New Wallet"
        visible={isModalOpen}
        onCancel={() => setIsModalOpen(false)}
        footer={null}
        className="wallets-add-modal"
      >
        <Input
          placeholder="Wallet Name"
          value={newWallet.name}
          onChange={(e) => setNewWallet({ ...newWallet, name: e.target.value })}
          className="wallets-input-field"
        />
        <Input
          placeholder="Public Key (Address)"
          value={newWallet.public_key}
          onChange={(e) => setNewWallet({ ...newWallet, public_key: e.target.value })}
          className="wallets-input-field"
        />
        <Input
          placeholder="Private Key"
          value={newWallet.private_key}
          onChange={(e) => setNewWallet({ ...newWallet, private_key: e.target.value })}
          className="wallets-input-field"
        />
        <Button type="primary" onClick={handleAddWallet} className="wallets-add-button">
          Add Wallet
        </Button>
      </Modal>
    </div>
  );
}

export default ManageWallets;
