import { useEffect, useRef, useState } from 'react';
import { Button } from 'react-bootstrap';
import * as apiServices from '../../helpers/apiServices';

function SnipingTerminal() {
  const [statusMessages, setStatusMessages] = useState([]);
  const [isSniping, setIsSniping] = useState(false);
  const intervalRef = useRef(null);

  useEffect(() => {
    if (isSniping) {
      intervalRef.current = setInterval(fetchLiveStatus, 2000); // Poll every 2 seconds
    } else {
      clearInterval(intervalRef.current);
    }

    return () => clearInterval(intervalRef.current);
  }, [isSniping]);

  const fetchLiveStatus = async () => {
    try {
      const response = await apiServices.getSnipingStatus();
      if (Array.isArray(response)) {
        setStatusMessages((prevMessages) => [...prevMessages, ...response]);
      } else {
        console.error("Unexpected response format:", response);
      }
    } catch (error) {
      console.error("Error fetching sniping status:", error);
    }
  };

  const handleStartStopSniping = async () => {
    try {
      if (isSniping) {
        // Implement stop sniping logic here if needed
        console.log("Stopping sniping...");
        setIsSniping(false);
      } else {
        // Clear existing messages and start sniping
        setStatusMessages([]); // Clear the status messages to only show new updates
        await apiServices.startSniping();
        console.log("Sniping process started successfully.");
        setIsSniping(true);
      }
    } catch (error) {
      console.error("Error starting/stopping sniping:", error);
    }
  };

  return (
    <div className="p-3 terminal rounded shadow-sm mb-4">
      <h5 className="text-white">Live Sniping Status</h5>
      <div className="terminal-content p-3 bg-secondary rounded" style={{ height: '200px', overflowY: 'auto' }}>
        {statusMessages.length > 0 ? (
          statusMessages.map((message, index) => (
            <div key={index} className="text-light">
              <p><strong>Timestamp:</strong> {message.timestamp}</p>
              <p><strong>Token:</strong> {message.token}</p>
              <p><strong>Status:</strong> {message.status}</p>
              <p><strong>Details:</strong> {message.details}</p>
            </div>
          ))
        ) : (
          <div className="text-muted">No current status messages.</div>
        )}
      </div>
      <Button
        className="mt-3 w-100"
        style={{ backgroundColor: isSniping ? '#E63946' : '#10B981', border: 'none' }}
        onClick={handleStartStopSniping}
      >
        {isSniping ? 'Stop Sniping' : 'Start Sniping'}
      </Button>
    </div>
  );
}

export default SnipingTerminal;
