import axios from "axios";


const API_URL = process.env.REACT_APP_API_URL || "http://localhost:8000/api";

const axiosApi = axios.create({
  baseURL: API_URL,
  headers: {
    "Content-Type": "application/json",
  },
});


// Add an authorization header with the token from localStorage, if available
axiosApi.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem("accessToken"); // Retrieve token directly from localStorage
    if (token) {
      config.headers["Authorization"] = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Handle responses and errors
axiosApi.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response) {
      switch (error.response.status) {
        case 401:
          console.error("Unauthorized access - redirect to login or show error");
          // Optional: Redirect to login page or clear session on 401 errors
          break;
        case 403:
          console.error("Forbidden - you do not have access to this resource.");
          break;
        case 500:
          console.error("Server error - please try again later.");
          break;
        default:
          console.error("An error occurred: ", error.response.data);
      }
    }
    return Promise.reject(error);
  }
);

// Define HTTP methods

// GET request
export async function get(url, config = {}) {
  return axiosApi.get(url, { ...config }).then((response) => response.data);
}

// POST request
export async function post(url, data, config = {}) {
  return axiosApi.post(url, data, { ...config }).then((response) => response.data);
}

// PUT request
export async function put(url, data, config = {}) {
  return axiosApi.put(url, data, { ...config }).then((response) => response.data);
}

// DELETE request
export async function del(url, config = {}) {
  return axiosApi.delete(url, { ...config }).then((response) => response.data);
}

export default axiosApi;
