// src/components/Settings.js

import { message } from 'antd';
import { useEffect, useState } from 'react';
import { getSettings, getWallets, updateSetting } from '../../helpers/apiServices';
import './bot.css';

function Settings() {
  const [settings, setSettings] = useState({
    rpcUrl: '',
    discordWebhook: '',
    telegramBotToken: '',
    telegramChannelId: '',
    selectedWallet: '',
    collectFees: 'No',
  });
  const [isEditing, setIsEditing] = useState(null);
  const [newSetting, setNewSetting] = useState('');
  const [wallets, setWallets] = useState([]); // Wallet options for dropdown

  useEffect(() => {
    fetchSettings();
    fetchWallets(); // Fetch wallets for the dropdown
  }, []);

  const fetchSettings = async () => {
    try {
      const data = await getSettings();
      setSettings(data);
    } catch (error) {
      message.error(`Error fetching settings: ${error.message || 'Unknown error'}`);
    }
  };

  const fetchWallets = async () => {
    try {
      const walletData = await getWallets();
      setWallets(walletData);
    } catch (error) {
      message.error(`Error fetching wallets: ${error.message || 'Unknown error'}`);
    }
  };

  const handleEdit = (key) => {
    setIsEditing(key);
    setNewSetting(settings[key]);
  };

  const handleSave = async (key) => {
    try {
      await updateSetting(key, newSetting);
      setIsEditing(null);
      fetchSettings();
    } catch (error) {
      message.error(`Error saving setting: ${error.message || 'Unknown error'}`);
    }
  };

  return (
    <div className="settings-container padding-top-container">
      <h2 className="settings-heading">Settings</h2>

      <table className="settings-table">
        <thead>
          <tr>
            <th className="settings-header-cell">Setting</th>
            <th className="settings-header-cell">Value</th>
            <th className="settings-header-cell">Action</th>
          </tr>
        </thead>
        <tbody>
          {/* RPC URL */}
          <tr>
            <td className="settings-cell">RPC URL Endpoint</td>
            <td className="settings-cell">
              {isEditing === 'rpcUrl' ? (
                <input
                  type="text"
                  value={newSetting}
                  onChange={(e) => setNewSetting(e.target.value)}
                  className="settings-input"
                />
              ) : (
                settings.rpcUrl || 'Not set'
              )}
            </td>
            <td className="settings-cell">
              {isEditing === 'rpcUrl' ? (
                <button onClick={() => handleSave('rpcUrl')} className="save-button">
                  Save
                </button>
              ) : (
                <button onClick={() => handleEdit('rpcUrl')} className="edit-button">
                  Edit
                </button>
              )}
            </td>
          </tr>

          {/* SELECT WALLET */}
          <tr>
            <td className="settings-cell">SELECT WALLET (Public Address)</td>
            <td className="settings-cell">
              {wallets.length === 0 ? (
                'No wallets added'
              ) : isEditing === 'selectedWallet' ? (
                <select
                  value={newSetting}
                  onChange={(e) => setNewSetting(e.target.value)}
                  className="settings-input"
                >
                  <option value="">Select a wallet</option>
                  {wallets.map((wallet) => (
                    <option key={wallet.id} value={wallet.public_key}>
                      {wallet.public_key}
                    </option>
                  ))}
                </select>
              ) : (
                settings.selectedWallet || 'Not set'
              )}
            </td>
            <td className="settings-cell">
              {isEditing === 'selectedWallet' ? (
                <button onClick={() => handleSave('selectedWallet')} className="save-button">
                  Save
                </button>
              ) : (
                <button onClick={() => handleEdit('selectedWallet')} className="edit-button">
                  Edit
                </button>
              )}
            </td>
          </tr>

          {/* COLLECT FEES */}
          <tr>
            <td className="settings-cell">COLLECT FEES</td>
            <td className="settings-cell">
              {isEditing === 'collectFees' ? (
                <select
                  value={newSetting}
                  onChange={(e) => setNewSetting(e.target.value)}
                  className="settings-input"
                >
                  <option value="Yes">Yes</option>
                  <option value="No">No</option>
                </select>
              ) : (
                settings.collectFees || 'No'
              )}
            </td>
            <td className="settings-cell">
              {isEditing === 'collectFees' ? (
                <button onClick={() => handleSave('collectFees')} className="save-button">
                  Save
                </button>
              ) : (
                <button onClick={() => handleEdit('collectFees')} className="edit-button">
                  Edit
                </button>
              )}
            </td>
          </tr>

          {/* Discord Webhook */}
          <tr>
            <td className="settings-cell">Discord Webhook</td>
            <td className="settings-cell">
              {isEditing === 'discordWebhook' ? (
                <input
                  type="text"
                  value={newSetting}
                  onChange={(e) => setNewSetting(e.target.value)}
                  className="settings-input"
                />
              ) : (
                settings.discordWebhook || 'Not set'
              )}
            </td>
            <td className="settings-cell">
              {isEditing === 'discordWebhook' ? (
                <button onClick={() => handleSave('discordWebhook')} className="save-button">
                  Save
                </button>
              ) : (
                <button onClick={() => handleEdit('discordWebhook')} className="edit-button">
                  Edit
                </button>
              )}
            </td>
          </tr>

          {/* Telegram Bot Token */}
          <tr>
            <td className="settings-cell">Telegram Bot Token</td>
            <td className="settings-cell">
              {isEditing === 'telegramBotToken' ? (
                <input
                  type="text"
                  value={newSetting}
                  onChange={(e) => setNewSetting(e.target.value)}
                  className="settings-input"
                />
              ) : (
                settings.telegramBotToken || 'Not set'
              )}
            </td>
            <td className="settings-cell">
              {isEditing === 'telegramBotToken' ? (
                <button onClick={() => handleSave('telegramBotToken')} className="save-button">
                  Save
                </button>
              ) : (
                <button onClick={() => handleEdit('telegramBotToken')} className="edit-button">
                  Edit
                </button>
              )}
            </td>
          </tr>

          {/* Telegram Channel ID */}
          <tr>
            <td className="settings-cell">Telegram Channel ID</td>
            <td className="settings-cell">
              {isEditing === 'telegramChannelId' ? (
                <input
                  type="text"
                  value={newSetting}
                  onChange={(e) => setNewSetting(e.target.value)}
                  className="settings-input"
                />
              ) : (
                settings.telegramChannelId || '0'
              )}
            </td>
            <td className="settings-cell">
              {isEditing === 'telegramChannelId' ? (
                <button onClick={() => handleSave('telegramChannelId')} className="save-button">
                  Save
                </button>
              ) : (
                <button onClick={() => handleEdit('telegramChannelId')} className="edit-button">
                  Edit
                </button>
              )}
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  );
}

export default Settings;
