import axios from "axios";

// Base URLs for API endpoints
const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:8000/api";
const DEX_SCREENER_BASE_URL = "https://api.dexscreener.com";
const JUPITER_API_BASE_URL = "https://quote-api.jup.ag/v1";

// Create an axios instance with base configuration
const axiosApi = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    "Content-Type": "application/json",
  },
});

// Interceptor to add authorization token to headers
axiosApi.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem("accessToken");
    if (token) {
      config.headers["Authorization"] = `Token ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Endpoint paths
const ENDPOINTS = {
  LOGIN: "/login/",
  REGISTER: "/register/",
  USER: "/user/",
  PROFILE: "/profile/",
  WALLET: "/wallets/",
  SELECTED_WALLET: "/wallets/selected/",
  SETTINGS: "/settings/",
  EXECUTE_TRANSACTION: "/transactions/execute/",
  TOKENS: "/tokens/",
  FETCH_TOKENS: "/fetch-tokens/",
  TOKEN_PRICES: "/tokenPrice/",
  SNIPING_TOKENS: "/sniping-tokens/",
  SNIPING_LOGS: "/snipe/logs/",
  START_SNIPING: "/snipe/start/",
  ADD_SNIPING_TOKEN: "/sniping-tokens/add/",
  UPDATE_SNIPING_TOKEN: (id) => `/sniping-tokens/${id}/update/`,
  DELETE_SNIPING_TOKEN: (id) => `/sniping-tokens/${id}/delete/`,
  CONFIG_PROFILES: "/configuration-profile/",
  ADD_CONFIG_PROFILE: "/configuration-profile/add/",
  UPDATE_CONFIG_PROFILE: (id) => `/configuration-profile/${id}/update/`,
  DELETE_CONFIG_PROFILE: (id) => `/configuration-profile/${id}/delete/`,
};

// Authentication functions
export const loginUser = async (data) => {
  try {
    const response = await axiosApi.post(ENDPOINTS.LOGIN, data);
    const token = response.data.token;
    if (token) {
      localStorage.setItem("accessToken", token); // Save token to localStorage
    }
    return response.data;
  } catch (error) {
    throw error.response?.data || error;
  }
};

export const registerUser = async (data) => {
  try {
    const response = await axiosApi.post(ENDPOINTS.REGISTER, data);
    return response.data;
  } catch (error) {
    throw error.response?.data || error;
  }
};

