export const fetchTokens = async () => {
    try {
      const response = await axiosApi.get(ENDPOINTS.TOKENS);
      // Map or format the response data if needed
      return response.data.map((token) => ({
        name: token.name || 'N/A',
        address: token.address || 'N/A',
        balance: token.balance || 0,
        symbol: token.symbol || 'N/A',
      }));
    } catch (error) {
      console.error("Error fetching tokens:", error.response?.data || error.message);
      throw new Error('Failed to fetch tokens from the backend.');
    }
  };
  

export const fetchTokensFromBackend = async () => {
  try {
    const response = await axiosApi.get(ENDPOINTS.FETCH_TOKENS);
    if (response.data && response.data.tokens) {
      return response.data.tokens;
    } else {
      throw new Error("Unexpected response format from backend");
    }
  } catch (error) {
    console.error("Error fetching tokens from backend:", error.response?.data || error.message);
    throw new Error(error.response?.data?.error || "Failed to fetch tokens from backend");
  }
};


